import sys

MOD = 1_000_000_007

def main():
    data = sys.stdin.readline().strip()
    if not data:
        return

    K = int(data)

    if K % 2 == 0:
        m = K // 2
        ans = (6 * pow(2, m, MOD) - 6 - 2 * m) % MOD
    else:
        m = K // 2
        ans = (pow(2, m + 3, MOD) - 2 * m - 7) % MOD

    print(ans)

if __name__ == "__main__":
    main()
